-- WoW Forever: quest objects for live quests that had none in our world: quest givers and turn-ins that are objects
-- (notes, chests, cauldrons, graves) and the objects a quest has you use (sentinel stones, soil, cannon ammunition, candles,
-- bonfires). Templates: where the Everlake world data (github.com/buildthehomelab/wow-everlake-world-data, GPL-3.0, its
-- 2026_11_19_995 file, from Icy Veins' WoW Forever database) has the object, its row as it is there; the five it lacks
-- (Spear of Mannoroth, Illari's Loot Cache, Half-Buried Mech, Access Hatch, Mysterious Chest) are plain quest-giver objects
-- with name and model from Wowhead. A template is only added where the world has none, so this and the Everlake file can run
-- in either order. Spawns: map spots from Wowhead's WoW Forever object pages (www.wowhead.com/forever, read 2026-11-20/21),
-- turned into world coordinates with the per-zone fit, ground height read from the map files. An object is only spawned
-- where the world has no spawn of it yet. Respawn 120 s (use objects 30 s), orientation 0 (ESTIMATED). Safe to run again.
DELETE FROM `gameobject` WHERE `guid` BETWEEN 47501100 AND 47501199;
-- Spear of Mannoroth (409311)
INSERT INTO `gameobject_template` (`entry`,`type`,`displayId`,`name`,`size`,`VerifiedBuild`)
SELECT 409311,2,5812,'Spear of Mannoroth',1,-1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `gameobject_template` WHERE `entry`=409311);
